import Link from "next/link";

/*
 * Brand images are generated by `npm run brand`. Every one is pinned to its natural
 * aspect ratio (fixed height, auto width, no max-width clamp, no flex shrink) so a
 * squeezed row or grid column can never crush or stretch the artwork.
 */
const LOCK = "block w-auto max-w-none shrink-0 object-contain";

/** Green can on the page's own background — the app's corner mark. `divider` adds a rule to its right. */
export function MarkBlock({ className = "", divider = true }: { className?: string; divider?: boolean }) {
  return (
    <Link
      href="/"
      aria-label="Dump home"
      className={`grid shrink-0 place-items-center bg-transparent px-3 ${divider ? "border-r-3 border-ink" : ""} ${className}`}
    >
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img src="/brand/mark-green.webp" alt="" width={21} height={36} className={`h-9 ${LOCK}`} />
    </Link>
  );
}

/** Full logo with wordmark. */
export function Logo({ tone = "ink", className = "" }: { tone?: "ink" | "green"; className?: string }) {
  return (
    // eslint-disable-next-line @next/next/no-img-element
    <img src={`/brand/logo-${tone}.webp`} alt="Dump" width={293} height={600} className={`${LOCK} ${className}`} />
  );
}

/** The flaming can used for the Dumpster Fire reaction. */
export function FireIcon({ size = 24, className = "" }: { size?: number; className?: string }) {
  return (
    // eslint-disable-next-line @next/next/no-img-element
    <img
      src="/brand/fire.webp"
      alt=""
      width={Math.round(size * 0.494)}
      height={size}
      style={{ height: size }}
      className={`${LOCK} ${className}`}
    />
  );
}
